set -u; mkdir -p /daodan/state/tools/bin "$HOME" /daodan/state/venvs
{ tar -xzf /daodan/state/in/node.tar.gz -C /daodan/state/tools && mv /daodan/state/tools/node-v24.22.3-linux-x64 /daodan/state/tools/node ; } >&2 || echo 'DAODAN-MISSING node@24.22.3' >&2
export PATH=/daodan/state/tools/corepack/bin:$PATH; [ -x /daodan/state/tools/corepack/bin/corepack ] || { npm install -g --prefix /daodan/state/tools/corepack --engine-strict --no-audit --no-fund --loglevel=error "corepack@>=0.31.0 <=0.36.0" >&2 || echo 'DAODAN-MISSING corepack@>=0.31.0' >&2; }
